def calculate_turan_edges(m, k):
    n_i = [m // k] * k
    for i in range(m % k):
        n_i[i] += 1

    edges = 0
    for i in range(k):
        for j in range(i + 1, k):
            edges += n_i[i] * n_i[j]
    return edges

